@startuml

class Employee {
  + IdentifyingNumber : int
  + Name : string
  + Address : string
}

class PartAccessory {
  + Category : string
  + SerialNumber : string
  + Price : double
}

class Car {
  + LicensePlate : string
  + Make : string
  + Model : string
  + Color : string
}

class Owner {
  + Name : string
  + IdentifyingNumber : int
  + Address : string
  + Phone : string
}

class AssemblyService {
  + Kms : int
  + WorkHours : float
  + AdmissionDate : date
  + FinishDate : date
}

Employee "1" -- "*" AssemblyService : responsible for
AssemblyService "*" -- "1" Car : executed in
AssemblyService "*" -- "*" PartAccessory : fits
Car "1" -- "*" AssemblyService
Car "*" -- "*" PartAccessory : fits models
Owner "1" -- "*" Car : owns

@enduml

